\section{First-order Logic}
\label{sec-logic}

\begin{theorem}[Motzkin's Transposition Theorem~\cite{Schrijver99}]
\label{thm-motzkin}
Let $A \in \mathbb{K}^{m \times n}$, $B \in \mathbb{K}^{\ell \times
n}$, $b \in \mathbb{K}^m$, and $d \in \mathbb{K}^\ell$.
\eqref{eq-motzkin1} and \eqref{eq-motzkin2} are equivalent.
\begin{align}
&\hspace{14.7mm} \forall x \in \mathbb{K}^n.\;
  \neg (Ax \leq b \;\land\; Bx < d)
\tag{M1}\label{eq-motzkin1} \\[2mm]
&\begin{aligned}
\exists \lambda \in \mathbb{K}^m \;\exists \mu \in \mathbb{K}^\ell.\;
  &\lambda \geq 0 \;\land\; \mu \geq 0 \\
  \land\; &\tr{\lambda} A + \tr{\mu} B = 0
  \;\land\;  \tr{\lambda} b + \tr{\mu} d \leq 0 \\
  \land\; &( \tr{\lambda} b < 0 \;\lor\; \mu \neq 0 )

\land\; &( \tr{\lambda} b < 0 \;\lor\; \mu \neq 0 )
\end{aligned}\tag{M2}\label{eq-motzkin2}
\end{align}
\end{theorem}

\begin{theorem}[Strong duality theorem]\label{thm-strong-duality}
Let $A \in \mathbb{K}^{m \times n}$, $b \in \mathbb{K}^m$, and
$c \in \mathbb{K}^n$.  Define the linear programming problem $P
= \{ \tr{c} x \mid A x \leq b \}$ and its dual $D = \{ \tr{b}
y \mid \tr{A} y = c, y \geq 0 \}$.  If either of $P$ or $D$ is
non-empty, then $\sup P = \inf D$.
\end{theorem}
\begin{proof}
See the literature on linear programming, e.g.\ \cite{Schrijver99}.
\end{proof}

The duality theorem holds over the theory of the reals as well as the
rationals.  This is because a polyhedron defined by inequalities
involving only rational coefficients has only rational vertices.  If a
linear programming problem (or its dual respectively) has an optimal
solution, it always has a vertex as an optimal solution; hence there
is a rational optimum~\cite{Schrijver99}.

\begin{lemma}[Affine Farkas' Lemma]\label{lem-farkas-affine}
Let $A \in \mathbb{K}^{m \times n}$, $b \in \mathbb{K}^m$,
$c \in \mathbb{K}^n$, and $\delta \in \mathbb{K}$ such that $Ax \leq
b$ has a solution.  Then the following two formulae are equivalent.
\begin{align*}
\forall x \in \mathbb{K}^n.&\; Ax \leq b
  \rightarrow \tr{c} x \leq \delta \\
\exists \lambda \in \mathbb{K}^m.&\; \lambda \geq 0
  \;\land\; \tr{\lambda} A = \tr{c}
  \;\land\; \tr{\lambda} b \leq \delta
\end{align*}
\end{lemma}
\begin{proof}
We reformulate \autoref{lem-farkas-affine} in terms of linear
programming.  Let $P$ and $D$ be as in \autoref{thm-strong-duality}.
\begin{center}
Let $P \neq \emptyset$. Then
  $\sup P \leq \delta$ iff $\inf D \leq \delta$.
\end{center}
If $P$ is bounded, then $D$ is feasible and by

\begin{lemma}[Classic Farkas' Lemma]\label{lem-farkas-classic}
For all $A \in \mathbb{K}^{m \times n}$ and $b \in \mathbb{K}^m$ the
following two formulae are equivalent.
\begin{align*}
\forall x \in \mathbb{K}^n.&\; \neg Ax \leq b \\
\exists \lambda \in \mathbb{K}^m.&\;
  \lambda \geq 0 \;\land\; \tr{\lambda} A = 0
  \;\land\; \tr{\lambda} b < 0
\end{align*}
\end{lemma}
\begin{proof}
We proceed analogously to the proof of \autoref{lem-farkas-affine}.
Here $P$ is infeasible, consequently its dual $D$ is unbounded and
thus attains some negative value.
\end{proof}

The following Lemma is of technical nature.  We require it for the
proof of \autoref{thm-motzkin}.

\begin{lemma}[Closure of polyhedra]\label{lem-polyhedron-closure}
Let $X = \{ x \in \mathbb{K}^n \mid Ax \leq b, Bx <
d \} \neq \emptyset$.  The smallest closed set containing $X$ is $Y
= \{ x \in \mathbb{K}^n \mid Ax \leq b, Bx \leq d \}$.
\end{lemma}
\begin{proof}
$Y$ contains $X$ and is the finite intersection of closed half-spaces
and therefore closed.  We need to show that every point in
$Y \setminus X$ is the limit of a sequence of points in $X$.
%
Let $y \in Y \setminus X$ and since $X$ is not empty, we can pick an
$x \in X$.  For $0 < t \leq 1$,
\begin{align*}
A(tx + (1-t)y) &= tAx + (1-t)Ay \leq tb + (1-t)b = b, \\
B(tx + (1-t)y) &= tBx + (1-t)By < td + (1-t)d = d.
\end{align*}
We conclude that $tx + (1-t)y \in X$ for all $0 < t \leq 1$.  But
\begin{align*}

\end{align*}
We conclude that $tx + (1-t)y \in X$ for all $0 < t \leq 1$.  But
\begin{align*}
\lim_{t \rightarrow 0} \big( tx + (1-t)y \big) = y,
\end{align*}
therefore $y$ is in the closure of $X$.
\end{proof}

\begin{definition}[Semantics of lasso programs]\label{def-lasso-semantics}
Let $\prog = (\stemt, \loopt)$ be a lasso program over the domain
$\Sigma$.  A \emph{state} of $\prog$ is an element
$\sigma \in \Sigma$.  An \emph{execution} of $\prog$ is a (possibly
infinite) sequence of states $\sigma_0 \sigma_1 \ldots$ such that
$\sigma_0 \in \stemt$ and $(\sigma_i, \sigma_{i+1}) \in \loopt$ for
all $i \geq 0$.
\end{definition}

