\begin{example}\label{ex-running-1}
Consider the following lasso program $\prog_{y \geq 1}$.
\begin{center}
\begin{minipage}{35mm}
\begin{lstlisting}
assume($y = 1$);
while($q \geq 0$):
    $q$ := $q - y$;
    $y$ := $y + 1$;
\end{lstlisting}
\end{minipage}
\end{center}
We can represent the stem and loop transition of $\prog_{y \geq 1}$
with the following formulae.
\begin{align*}
\stemt(q, y) &\equiv y = 1 \\
\loopt(q, y, q', y') &\equiv q \geq 0 \;\land\; q' = q - y
  \;\land\; y' = y + 1
\end{align*}
An execution of $\prog_{y \geq 1}$ is $\sigma_0 \sigma_1 \sigma_2$
where
\begin{align*}
\sigma_0&: y \mapsto 1, q \mapsto 2, \\
\sigma_1&: y \mapsto 2, q \mapsto 1, \text{ and} \\
\sigma_2&: y \mapsto 3, q \mapsto -1.
\end{align*}
Since $q$ is negative in $\sigma_2$, there is no possible successor
state to $\sigma_2$.
\end{example}

\begin{lemma}[Linear lasso program normal form]\label{lem-lasso-nf}
For all \emph{linear lasso programs} $\prog = (\stemt, \loopt)$, the
formulae $\stemt$ and $\loopt$ can be written in the following normal
form.
\begin{align*}
\stemt(x)    &\equiv \bigvee_{n \in N}
  \big( B_n x \leq b_n
  \;\land\; B_n' x < b_n' \big) \\
\loopt(x,x') &\equiv \bigvee_{m \in M}
  \big( A_m \abovebelow{x}{x'} \leq c_m
  \;\land\; A_m' \abovebelow{x}{x'} < c_m' \big)
\end{align*}
$B_n$, $B_n'$, $A_m$, and $A_m'$ are matrices, $b_n$, $b_n'$, $c_m$,
and $c_m'$ are vectors, and $N$ and $M$ suitable finite index sets.
The program $\prog$ is conjunctive if and only if it has a normal form
with $\#N = \#M = 1$.
\end{lemma}
\begin{proof}
We transform the formulae $\stemt$ and $\loopt$ in negation normal
form such that negations occur only before atoms.  Then we rewrite
negated atoms using the following identities.
\begin{align*}

