\section{Invariants}
\label{sec-invariants}

Informally, an invariant is a property that always holds during
program execution.  Although our primary goal is to prove termination,
the inference of invariants can uncover information critical to this
goal.  In \autoref{sec-augmentation} we will discuss how we involve
invariants in the ranking function discovery process.

\begin{definition}[Invariant]\label{def-invariant}
A state $\sigma \in \Sigma$ of a lasso program $\prog$
is \emph{reachable} iff there is an execution of $\prog$ containing
$\sigma$.  A formula $\psi$ is called an \emph{invariant} of $\prog$
iff $\models \psi(\sigma)$ for all reachable states $\sigma$ of
$\prog$.
\end{definition}

\begin{definition}[Affine-linear invariant]\label{def-al-invariant}
An invariant $\psi(x)$ is an \emph{affine-linear invariant} if it is
of the form
\begin{align*}
\psi(x) \equiv \tr{s}x + t \rhd 0
\end{align*}
for some vector $s \in \mathbb{K}^n$, some value $t \in \mathbb{K}$,
and $\rhd \in \{ >, \geq \}$.  If $\rhd =\; >$, the invariant $\psi(x)$
is called \emph{strict} invariant; if $\rhd =\; \geq$, the invariant
$\psi(x)$ is called \emph{non-strict} invariant.
\end{definition}

\begin{definition}[Inductive invariant]\label{def-inductive-invariant}
A formula $\psi$ is called an \emph{inductive invariant} for a linear
lasso program $\prog$ iff the following two formulae hold.
\begin{align}
\forall \sigma \in \Sigma.&\;
\stemt(\sigma) \rightarrow \psi(\sigma) \label{eq-ii}\tag{II} \\
\forall \sigma, \sigma' \in \Sigma.&\;
\psi(\sigma) \land \loopt(\sigma, \sigma') \rightarrow \psi(\sigma')
\label{eq-ic}\tag{IC}
\end{align}
\end{definition}

\begin{example}\label{ex-running-3}
$\prog_{y \geq 1}$ from \autoref{ex-running-1} has the affine-linear
inductive invariant $y \geq 1$, since it is implied by the stem and
\begin{align*}
\mathbb{K} \models \forall q, y, q', y'.\;
  y \geq 1 \;\land\; (q \geq 0 \;\land\; q' = q - y
  \;\land\; y' = y + 1) \rightarrow y' \geq 1.
\end{align*}
\end{example}

\begin{remark}\label{rem-inductive}
Every inductive invariant is an invariant.
\end{remark}
\begin{proof}
By induction using \eqref{eq-ii} and \eqref{eq-ic}.
\end{proof}

\noindent
Invariants, that are not inductive invariants are
called \emph{non-inductive} invariants.

\begin{example}\label{ex-inductive-invariant}
The converse to \autoref{rem-inductive} does not hold: non-inductive
invariants exist.  Consider the program $\prog_\mathrm{inv}$:
\begin{align*}
\stemt(y, z) &\equiv y \geq 0 \;\land\; z \geq 0 \\
\loopt(y, z, y', z') &\equiv y' = z \;\land\; z' = y
\end{align*}
$y \geq 0$ and $z \geq 0$ are invariants of $\prog_\mathrm{inv}$:
initially $y$ and $z$ are non-negative and their values do not
decrease in the loop transition.  However, neither of the two
invariants is inductive since
\begin{align*}
y \geq 0 \;\land\; y' = z \;\land\; z' = y \rightarrow y' \geq 0
\end{align*}
is false for $y = z' = 1$, and $z = y' = -1$ (and analogously for
$z \geq 0$).  Intuitively, the conclusion $y' \geq 0$ depends on the
information that $z \geq 0$ and vice versa, so neither invariant can
be proven inductively on their own.
\end{example}

