\begin{definition}[Termination]\label{def-termination}
A lasso program \emph{terminates} iff it has no execution of infinite
length.
\end{definition}

\begin{definition}[Ranking function]\label{def-rf}
Let $\alpha$ be a set with well-ordering relation $<_\alpha$.
A \emph{ranking function} $f$ for a lasso program $\prog =
(\stemt, \loopt)$ on domain $\Sigma$ is a function
$f: \Sigma \to \alpha$ such that for all reachable states $\sigma$ and $\sigma'$
\begin{align}
\loopt(\sigma, \sigma') \rightarrow f(\sigma') <_\alpha f(\sigma).
\label{eq-rf}\tag{RF}
\end{align}
\end{definition}

