\begin{lemma}[Loop augmentation with invariants]\label{lem-invariant-aug}
Let $\T$ be a ranking function template, $\prog = (\stemt, \loopt)$ be
a lasso program, and $(\psi_\ell)_{\ell \in L}$ a finite number of
invariants of $\prog$.  If the formula
\begin{align}
\forall x, x'.\; \big( \loopt(x, x')
    \land \bigwedge_{\ell \in L} \psi_\ell(x) \big)
  \rightarrow \T(x, x') \label{eq-rft'}
\end{align}
is satisfiable, then $\prog$ terminates.
\end{lemma}
\begin{proof}
Because every $\psi_\ell$ holds at all reachable states of $\prog$, so
does $\bigwedge_{\ell \in L} \psi_\ell$.  Consider the transition
\begin{align*}
\loopt'(x, x') \equiv \Big( \bigwedge_{\ell \in L} \psi_\ell(x) \Big)
  \;\land\; \loopt(x, x').
\end{align*}
The two programs $\prog = (\stemt, \loopt)$ and $\prog' =
(\stemt, \loopt')$ are semantically equivalent: they have the same
executions.  Therefore $\prog$ terminates iff $\prog'$ terminates, and
the latter is equivalent to the satisfiability of \eqref{eq-rft'}
by \autoref{def-rft}.
\end{proof}

