\begin{theorem}\label{thm-nl-0}
Let $L$ be the index set of invariants, let $F$ and $D$ be the
function symbols and variables of the ranking function template $\T$
respectively.  Let $n$ denote the number of lasso program variables.
The constraints \eqref{eq-ii0} $\land$ \eqref{eq-ic0}
$\land$ \eqref{eq-ti0} have non-linear dimension
\begin{align*}
(n + 1)\#L + (n + 1)\#F + \#D.
\end{align*}
\end{theorem}
\begin{proof}
Non-linear operations occur only with the invariants $\psi(x)$ and the
ranking function template's atoms $\T_{i,j}(x, x')$.  Because we
cannot choose $x$ or $x'$ since they are universally quantified, we
have to choose as the set of variables that occur in non-linear
operations
\begin{align*}
V = \{ s_\ell, t_\ell \mid \ell \in L \} \cup D \cup F.
\end{align*}
The vectors $s_\ell$ and the affine-linear function symbols $f \in F$
have a total number of $n$ and $n + 1$ variables respectively. 
\end{proof}

\begin{theorem}\label{thm-nl-6}
Let $\T$ be a linear ranking function template and let $L' = L \times
I \times M$ as in \autoref{sec-constraints}: $L$ is the index set of
invariants, $M$ is the index set of the loop transition's disjunctions
in CNF and $I$ is the index set of conjunctions in the ranking
function template's DNF.  Let $\eta$ be a suitable coloring for $\T$.
The constraint \eqref{eq-ii6} $\land$ \eqref{eq-ic6}
$\land$ \eqref{eq-ti6} has non-linear dimension at most
\begin{align*}
\#M \cdot \deg_\T(\eta) + \#L'.
\end{align*}
\end{theorem}
\begin{proof}
We first count the number of \hyperref[thm-motzkin]{Motzkin's Theorem}
applications in transformation step 5:
\begin{itemize}
\item $\#L \cdot \#M \cdot \#I \cdot \#N$ from \eqref{eq-ii4},
\item $\#L \cdot (\#M)^2 \cdot \#I$ from \eqref{eq-ic4}, and
\item $\#I \cdot \#M$ from \eqref{eq-ti4}.
\end{itemize}

\item $\#I \cdot \#M$ from \eqref{eq-ti4}.
\end{itemize}
Let $n_\stemt$ be the total number of inequalities in the stem
transition and $n_\loopt$ be the total number of inequalities in the
loop transition.  Thus the constraint \eqref{eq-ii6}
$\land$ \eqref{eq-ic6} $\land$ \eqref{eq-ti6} has a total number of
\begin{align*}
\#L \cdot \#M \cdot \#I \cdot n_\stemt + \#L \cdot \#M \cdot
\#I \cdot n_\loopt + \#I \cdot n_\loopt
\end{align*}
Motzkin coefficients $\lambda$ and $\mu$, as well as $\#L'$ Motzkin
coefficients $\chi_1$ for invariants $\#M \cdot \deg_\T(\eta)$ Motzkin
coefficients $\zeta$ for the ranking function template.
\end{proof}

In order to eliminate more variables in our constraints, we introduce
non-decreasing invariants~\cite{HHLP13}, as a restricted class of
inductive invariants.

\begin{definition}[Non-decreasing invariant]
\label{def-non-decreasing}
An affine-linear inductive invariant $\psi(x) \equiv \tr{s} x + t \geq
0$ is \emph{non-decreasing} iff
\begin{align*}
\models \forall x, x'.\;
  \loopt(x, x') \rightarrow \tr{s} x' - \tr{s} x \geq 0.
\end{align*}
\end{definition}

Restricting the inductive invariants to non-decreasing invariants is
equivalent to fixing their Motzkin coefficients $\chi_1$ in the
invariant consecution \eqref{eq-ic6} to the value $1$.  This enables
the following corollary to \autoref{thm-nl-6}.

Restricting the inductive invariants to non-decreasing invariants is
equivalent to fixing their Motzkin coefficients $\chi_1$ in the
invariant consecution \eqref{eq-ic6} to the value $1$.  This enables
the following corollary to \autoref{thm-nl-6}.

\begin{corollary}\label{cor-nl-6}
Let $\T$, $M$ and $\eta$ as in \autoref{thm-nl-6}.  When using only
non-decreasing invariants, the constraint \eqref{eq-ii6}
$\land$ \eqref{eq-ic6} $\land$ \eqref{eq-ti6} has non-linear dimension
at most $\#M \cdot \deg_\T(\eta)$.
\end{corollary}

\begin{example}\label{ex-non-decreasing1}
The inductive invariant $y \geq 1$ from \autoref{ex-running-3} is in
fact non-decreasing:
\begin{align*}
\models \forall q, y, q', y'.\;
  q \geq 0 \;\land\; q' = q - y \;\land\; y' = y + 1
  \;\rightarrow\; y' - y \geq 0
\end{align*}
\end{example}

\begin{example}\label{ex-non-decreasing2}
Consider the program $\prog_\mathrm{diff42}$~\cite{HHLP13}.
\begin{center}
\begin{minipage}{40mm}
\begin{lstlisting}
$q$ := $y + 42$;
while ($q \geq 0$):
    $y$ := $2 \cdot y - q$;
    $q$ := $(y + q) / 2$;
\end{lstlisting}
\end{minipage}
\end{center}
$\prog_\mathrm{diff42}$ instantiates the affine template with the
ranking function $f(q, y) = q + 1$ and the non-decreasing supporting
invariant $q - y \geq 42$:
\begin{align*}
q' - y' = \frac{y + q}{2} - (2y - q)
  = \frac{3}{2}(q - y)
  \geq \frac{3}{2} \cdot 42
  \geq 42
\end{align*}
\end{example}

Non-decreasing inductive invariants are weaker in expressiveness,
however they still cover a wide range of practical cases.  An inductive
invariant is non-decreasing if
\begin{itemize}
\item the invariant involves only variables that are not
  modified by the loop transition, or
\item the invariant is an equality.
\end{itemize}

\begin{example}\label{ex-non-decreasing3}
The variable $\chi_1$ in the invariant consecution \eqref{eq-ic5}
cannot be generally restricted to any finite set of values analogously
to \autoref{def-non-decreasing} without losing solutions.  Let $\alpha
> 1$ be some fixed constant and consider the following linear lasso
program $\prog_\alpha$:
\begin{center}
\begin{minipage}{50mm}
\begin{lstlisting}
assume($y := \alpha$);
while ($q \geq 0$):
    $q$ := $q - y$;
    $y$ := $\frac{1}{\alpha}(y + \alpha - 1)$;
\end{lstlisting}
\end{minipage}
\end{center}
The program $\prog_\alpha$ terminates, because $y \geq 1$ is an
invariant of $\prog_\alpha$.  Furthermore, the invariant is inductive:
the stem $y = \alpha$ implies $y \geq 1$, and
\begin{align*}
y' = \frac{y + \alpha - 1}{\alpha}
   = \frac{y}{\alpha} + \frac{\alpha - 1}{\alpha}
   \geq \frac{1}{\alpha} + \frac{\alpha - 1}{\alpha}
   = 1.
\end{align*}

\geq \frac{1}{\alpha} + \frac{\alpha - 1}{\alpha}
   = 1.
\end{align*}
However, $y \geq 1$ is not a non-decreasing invariant:
\begin{align}
y' - y = \frac{y + \alpha - 1}{\alpha} - y
       = \frac{\alpha - 1}{\alpha} \cdot (1 - y).
\label{eq-ex-non-decreasing3}
\end{align}
We are stuck, because \eqref{eq-ex-non-decreasing3} cannot be inferred
to be non-negative: there is no lower bound on $-y$.  We have to
choose $\chi_1 = \frac{1}{\alpha}$ in \eqref{eq-ic6} because
\begin{align*}
y' - \frac{1}{\alpha} \cdot y
  = \frac{y + \alpha - 1}{\alpha} - \frac{1}{\alpha} \cdot y
  = \frac{\alpha - 1}{\alpha}
  \geq 0.
\end{align*}
In fact, every value $\chi_1 > \frac{1}{\alpha}$ will not work for the
same reason as in \eqref{eq-ex-non-decreasing3}.
\end{example}

\begin{corollary}\label{cor-linear}
If the linear ranking function template $\T$ has degree $\leq 0$ and
we consider only non-decreasing invariants, then the
constraint \eqref{eq-ii6} $\land$ \eqref{eq-ic6}
$\land$ \eqref{eq-ti6} is linear.
\end{corollary}
\begin{proof}
According to \autoref{cor-nl-6}, the constraints have non-linear
dimension at most $\#M \cdot \deg_\T(\eta)$ for a suitable coloring
$\eta$ of $\T$.  Consequently, for $\deg_\T(\eta) = 0$, we have no
non-linear operations.  Since there is no universal quantification,
the generated constraint is linear by \autoref{def-degree}.
\end{proof}

The constraints generated by \ref{eq-rft-affine} are due Podelski and
Rybalchenko~\cite{PR04}.  In \cite{HHLP13} this template is extended
to incorporate non-decreasing inductive invariants, and the generated
template coincides with the one generated here, if we restrict
ourselves to non-decreasing invariants and conjunctive linear lasso
programs.


