\begin{align*}
\loopt(x, x') &\equiv Ax \leq b \;\land\; A'x < b', \\
\psi(x) &\equiv \tr{s} x + t \geq 0.
\end{align*}
After applying \hyperref[thm-motzkin]{Motzkin's Theorem} in
transformation step 5, we get \eqref{eq-ic5} and fixing the value of
$\chi_2$ according to \autoref{thm-omit-quantifiers}, the
constraints \eqref{eq-ic6} corresponding to \eqref{eq-cad1} are
\begin{align}
\begin{aligned}
\exists \lambda, \chi, \mu \geq 0.\;
&\tr{\lambda} A + \tr{\mu} A' + \tr{\abovebelow{0}{s}}
  - \chi\tr{\abovebelow{s}{0}} = 0 \\

\label{eq-cad-k4}
\end{align}
%
We solve \eqref{eq-cad-k3} for $s_j$ and eliminate $s_j$
from \eqref{eq-cad-k2} yielding the following system of equations.
\begin{align}
\chi &\geq 0 \label{eq-cad-l0} \\
\lambda_i &\geq 0, &\text{for } 1 \leq i \leq m \label{eq-cad-l1} \\
\sum_{i=1}^m (a_{i,j} + a_{i,n+j} \chi) \lambda_i &= 0,
&\text{for } 1 \leq j \leq n
\label{eq-cad-l2} \\
\sum_{i=1}^m c_i \lambda_i - (1 - \chi) t &\leq 0
\label{eq-cad-l4}
\end{align}

We ignore the constraint \eqref{eq-cad-l4} because in the case where
$\chi \neq 1$, we can always assign $t$ such that this inequality
holds.  For the projection we choose the ordering
$\lambda_1, \ldots, \lambda_m, \chi$.  The set of polynomials for the
CAD is
\begin{align}
P = \{ \chi, \lambda_i \mid 0 \leq i \leq m \}
\cup \Big\{ \sum_{i=1}^m  (a_{i,n+j} \chi + a_{i,j}) \lambda_i
  \mid 0 \leq j \leq n \Big\}.
\label{eq-cad-poly}
\end{align}
In particular, the coefficient polynomials to $\lambda_i$
in \eqref{eq-cad-poly} are linear in $\chi$.

\begin{lemma}\label{lem-cad-form}
In every projection step $k$ in the CAD of \eqref{eq-cad-poly}, the
set of polynomials
\begin{align}
P_k = \{ \lambda_i \mid k \leq i \leq m \}
\;\cup\; \Big\{ \sum_{i=k}^m p_{i,j}(\chi) \lambda_i
  \mid j \in J_k \Big\}
\;\cup\; \{ q_\ell(\chi) \mid \ell \in L_k \}
\label{eq-cad-form}
\end{align}
for suitable index sets $J$ and $L$.  The polynomials $p_{i,j}$ and
$q_\ell$ only involve the variable $\chi$.
\end{lemma}
\begin{proof}
We proceed inductively.  Clearly \eqref{eq-cad-poly} satisfies this
criterion.  Consider the projection of $\lambda_k$.
\begin{itemize}
\item For every polynomial $p \in P_k$, we take $p(\lambda_k = 0)$.
  This yields $\lambda_{k+1}, \ldots, \lambda_m$, $\sum_{i=k+1}^m
  p_{i,j}(\chi) \lambda_i$ and preserves $q_\ell(\chi)$.
\item For every polynomial $p \in P_k$, we calculate

\Big) \lambda_i.
\end{align*}
  This is again of the form given in \eqref{eq-cad-form}. \qedhere
\end{itemize}
\end{proof}

